const cache = new Map<string, ComponentType<Record<string, unknown>> | null>();

export function loadPreviewComponent(
  exportName: string,
): ComponentType<Record<string, unknown>> | null {
  if (cache.has(exportName)) {
    return cache.get(exportName) ?? null;
  }

  const loader = previewComponentLoaders[exportName];
  if (!loader) {
    cache.set(exportName, null);
    return null;
  }

  try {
    const component = loader();
    cache.set(exportName, component);
    return component;
  } catch {
    cache.set(exportName, null);
    return null;
  }
}
